#!/usr/bin/env python3
import json
from pathlib import Path

import pandas as pd

SOURCES = [
    ("source_a", "/data/source_a/users.json"),
    ("source_b", "/data/source_b/users.csv"),
    ("source_c", "/data/source_c/users.parquet"),
]

MAPPINGS = {
    "source_a": {
        "id": "user_id",
        "full_name": "name",
        "email": "email",
        "registration_date": "created_date",
        "status": "status",
    },
    "source_b": {
        "user_id": "user_id",
        "name": "name",
        "email_address": "email",
        "created_at": "created_date",
        "is_active": "status",
    },
    "source_c": {
        "userId": "user_id",
        "userName": "name",
        "email": "email",
        "joined": "created_date",
        "active": "status",
    },
}

OUTPUT_FIELDS = ["user_id", "name", "email", "created_date", "status"]
CONFLICT_FIELDS = ["name", "email", "created_date", "status"]


def read_source(name, path):
    p = Path(path)
    if p.suffix == ".json":
        df = pd.read_json(p)
    elif p.suffix == ".csv":
        df = pd.read_csv(p)
    elif p.suffix == ".parquet":
        df = pd.read_parquet(p)
    else:
        raise ValueError(f"Unsupported file type: {path}")

    df = df.rename(columns=MAPPINGS[name])
    for field in OUTPUT_FIELDS:
        if field not in df.columns:
            df[field] = None
    return df[OUTPUT_FIELDS].copy()


def normalize_status(value):
    if pd.isna(value):
        return None
    if isinstance(value, bool):
        return "active" if value else "inactive"
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if value == 1:
            return "active"
        if value == 0:
            return "inactive"
    text = str(value).strip().lower()
    if text in {"true", "t", "yes", "y", "1", "active"}:
        return "active"
    if text in {"false", "f", "no", "n", "0", "inactive"}:
        return "inactive"
    return str(value).strip()


def normalize_date(value):
    if pd.isna(value):
        return None
    dt = pd.to_datetime(value, errors="coerce")
    if pd.isna(dt):
        return str(value).strip()
    return dt.strftime("%Y-%m-%d")


def normalize_numeric(value):
    if pd.isna(value):
        return None
    return int(float(value))


def normalize_source(df):
    df = df.copy()
    df["user_id"] = df["user_id"].map(normalize_numeric)
    df = df[df["user_id"].notna()].copy()
    df["user_id"] = df["user_id"].astype("int64")
    for field in ["name", "email"]:
        df[field] = df[field].map(
            lambda v: None if pd.isna(v) else str(v)
        )
    df["created_date"] = df["created_date"].map(normalize_date)
    df["status"] = df["status"].map(normalize_status)
    return df


def main():
    records = {source: {} for source, _ in SOURCES}

    for source, path in SOURCES:
        df = normalize_source(read_source(source, path))
        for row in df.to_dict(orient="records"):
            records[source][row["user_id"]] = row

    all_ids = sorted(
        set().union(*(set(records[source]) for source, _ in SOURCES))
    )

    merged_rows = []
    conflicts = []

    for user_id in all_ids:
        available = {
            source: records[source][user_id]
            for source, _ in SOURCES
            if user_id in records[source]
        }

        output_row = {"user_id": user_id}
        for field in OUTPUT_FIELDS[1:]:
            selected = None
            for source, _ in SOURCES:
                if source in available:
                    value = available[source].get(field)
                    if value is not None and not (
                        isinstance(value, float) and pd.isna(value)
                    ):
                        selected = value
                        break
            output_row[field] = selected

        merged_rows.append(output_row)

        for field in CONFLICT_FIELDS:
            values = {}
            for source, _ in SOURCES:
                if source in available:
                    value = available[source].get(field)
                    if value is not None and not (
                        isinstance(value, float) and pd.isna(value)
                    ):
                        values[source] = value

            if len(set(values.values())) > 1:
                selected = None
                for source, _ in SOURCES:
                    if source in values:
                        selected = values[source]
                        break
                conflicts.append(
                    {
                        "user_id": user_id,
                        "field": field,
                        "values": values,
                        "selected": selected,
                    }
                )

    merged = pd.DataFrame(merged_rows, columns=OUTPUT_FIELDS)
    merged["user_id"] = merged["user_id"].astype("int64")
    for field in ["name", "email", "created_date", "status"]:
        merged[field] = merged[field].astype("object")
    merged = merged.sort_values("user_id").reset_index(drop=True)
    merged.to_parquet("/app/merged_users.parquet", index=False)

    report = {
        "total_conflicts": len(conflicts),
        "conflicts": conflicts,
    }
    with open("/app/conflicts.json", "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2, ensure_ascii=False)
        f.write("\n")

    print(f"Wrote {len(merged)} users and {len(conflicts)} conflicts")


if __name__ == "__main__":
    main()
EOF
